require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/data-slot.php';
if (!$ingelogd) { header('Location: ../beheer.php'); exit; }
if (!function_exists('authHeeftExplicietRecht') || !authHeeftExplicietRecht('gebruikers')) { http_response_code(403); echo 'Geen toegang tot Gebruikers.'; exit; }

$rechtenDef = require __DIR__ . '/gebruikers-rechten.php';
$rechtGroepen = $rechtenDef['groepen'] ?? [];
$gevoeligeRechten = $rechtenDef['gevoelig'] ?? [];
$alleRechten = [];
foreach ($rechtGroepen as $items) foreach ((array)$items as $k => $v) $alleRechten[$k] = $v;

function guEsc($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function guFlash(string $tekst, string $type='ok'): void { $_SESSION['gebruikers_module_flash']=['tekst'=>$tekst,'type'=>$type]; }
function guRedirect(): void { header('Location: gebruikers.php'); exit; }
function guVindIndex(array $gebruikers,string $naam): ?int { foreach($gebruikers as $i=>$g) if(isset($g['gebruikersnaam'])&&strcasecmp((string)$g['gebruikersnaam'],$naam)===0)return $i; return null; }
function guGekozenRechten(array $toegestaan): array { $gekozen=array_map('strval',(array)($_POST['tabs']??[])); return array_values(array_intersect(array_keys($toegestaan),$gekozen)); }
function guTrekSessiesIn(array &$g): void { $g['sessie_versie']=max(1,(int)($g['sessie_versie']??1))+1; }
function guDatum(?int $tijd): string { return $tijd?date('d-m-Y H:i',$tijd):'Nog niet geregistreerd'; }
function guAangemaakt(array $g): string { $t=strtotime((string)($g['aangemaakt']??'')); return $t===false?'Onbekend':date('d-m-Y',$t); }
function guWachtwoordDatum(array $g): string { $t=strtotime((string)($g['wachtwoord_gewijzigd']??'')); return $t===false?'Onbekend':date('d-m-Y H:i',$t); }
function guLeesLogOverzicht(string $pad): array {
    $resultaat=['login'=>[],'actie'=>[]];
    if(!is_file($pad))return $resultaat;
    $raw=@file_get_contents($pad);$data=$raw===false?null:json_decode($raw,true);if(!is_array($data))return $resultaat;
    foreach($data as $r){
        if(!is_array($r))continue;$naam=trim((string)($r['gebruiker']??''));$tijd=strtotime((string)($r['tijd']??''));if($naam===''||$tijd===false)continue;$k=strtolower($naam);
        if(($r['actie']??'')==='login'){if(!isset($resultaat['login'][$k])||$tijd>$resultaat['login'][$k])$resultaat['login'][$k]=$tijd;}
        else{if(!isset($resultaat['actie'][$k])||$tijd>$resultaat['actie'][$k])$resultaat['actie'][$k]=$tijd;}
    }
    return $resultaat;
}
function guLoginStatus(array $allePogingen,string $naam,int $venster,int $drempel):array{
    $sleutel='user:'.strtolower($naam);$nu=time();$recent=array_values(array_filter((array)($allePogingen[$sleutel]??[]),static fn($t)=>is_numeric($t)&&(int)$t>$nu-$venster));
    $aantal=count($recent);$minuten=0;if($aantal>=$drempel&&$recent)$minuten=max(1,(int)ceil((min($recent)+$venster-$nu)/60));
    return['aantal'=>$aantal,'geblokkeerd'=>$aantal>=$drempel,'minuten'=>$minuten];
}

$flash=$_SESSION['gebruikers_module_flash']??null;unset($_SESSION['gebruikers_module_flash']);

if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    if(!csrfOk()){guFlash('Sessie verlopen. Ververs de pagina en probeer het opnieuw.','fout');guRedirect();}
    $actie=(string)($_POST['actie']??'');$slot=dataSlotOpen();
    if(!$slot){guFlash('Opslaan is tijdelijk niet mogelijk omdat het dataslot niet kon worden verkregen.','fout');guRedirect();}
    try{
        $gebruikers=laadGebruikers($usersBestand);
        if($actie==='aanmaken'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$w=(string)($_POST['wachtwoord']??'');$h=(string)($_POST['wachtwoord_herhaald']??'');$tabs=guGekozenRechten($alleRechten);
            if($naam===''||!preg_match('/^[a-zA-Z0-9._-]{2,30}$/',$naam))guFlash('Gebruikersnaam moet 2 tot 30 tekens zijn: letters, cijfers, punt, streepje of underscore.','fout');
            elseif(strcasecmp($naam,'beheerder')===0)guFlash('“beheerder” is gereserveerd voor het hoofdbeheeraccount.','fout');
            elseif(guVindIndex($gebruikers,$naam)!==null)guFlash('Er bestaat al een account met deze gebruikersnaam.','fout');
            elseif(strlen($w)<10)guFlash('Een nieuw wachtwoord moet minimaal 10 tekens lang zijn.','fout');
            elseif($w!==$h)guFlash('De twee wachtwoorden komen niet overeen.','fout');
            else{$nu=date('c');$gebruikers[]=['gebruikersnaam'=>$naam,'hash'=>password_hash($w,PASSWORD_DEFAULT),'aangemaakt'=>$nu,'wachtwoord_gewijzigd'=>$nu,'sessie_versie'=>1,'actief'=>true,'tabs'=>$tabs];if(schrijfGebruikers($usersBestand,$gebruikers)){schrijfLog($logBestand,$huidigeGebruiker,'gebruiker_aangemaakt',$naam.' · '.count($tabs).' recht(en)');guFlash('Account “'.$naam.'” is aangemaakt.');}else guFlash('Account kon niet worden opgeslagen.','fout');}
        }elseif($actie==='rechten'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$tabs=guGekozenRechten($alleRechten);$idx=guVindIndex($gebruikers,$naam);
            if($idx===null)guFlash('Gebruiker niet gevonden.','fout');else{$gebruikers[$idx]['tabs']=$tabs;guTrekSessiesIn($gebruikers[$idx]);if(schrijfGebruikers($usersBestand,$gebruikers)){schrijfLog($logBestand,$huidigeGebruiker,'toegang_bijgewerkt',$naam.' · bestaande sessies ingetrokken');guFlash('Rechten van “'.$naam.'” zijn bijgewerkt. Bestaande sessies zijn ingetrokken.');}else guFlash('Rechten konden niet worden opgeslagen.','fout');}
        }elseif($actie==='wachtwoord'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$w=(string)($_POST['wachtwoord']??'');$h=(string)($_POST['wachtwoord_herhaald']??'');$idx=guVindIndex($gebruikers,$naam);
            if($idx===null)guFlash('Gebruiker niet gevonden.','fout');elseif(strlen($w)<10)guFlash('Het nieuwe wachtwoord moet minimaal 10 tekens lang zijn.','fout');elseif($w!==$h)guFlash('De twee wachtwoorden komen niet overeen.','fout');else{$gebruikers[$idx]['hash']=password_hash($w,PASSWORD_DEFAULT);$gebruikers[$idx]['wachtwoord_gewijzigd']=date('c');guTrekSessiesIn($gebruikers[$idx]);if(schrijfGebruikers($usersBestand,$gebruikers)){schrijfLog($logBestand,$huidigeGebruiker,'wachtwoord_reset',$naam.' · bestaande sessies ingetrokken');guFlash('Wachtwoord van “'.$naam.'” is gewijzigd. Bestaande sessies zijn ingetrokken.');}else guFlash('Wachtwoord kon niet worden opgeslagen.','fout');}
        }elseif($actie==='status'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$nieuwActief=(string)($_POST['actief']??'')==='1';$idx=guVindIndex($gebruikers,$naam);
            if($idx===null)guFlash('Gebruiker niet gevonden.','fout');elseif(!$nieuwActief&&!$isMaster&&strcasecmp($naam,$huidigeGebruiker)===0)guFlash('Je kunt je eigen account niet blokkeren.','fout');else{$gebruikers[$idx]['actief']=$nieuwActief;guTrekSessiesIn($gebruikers[$idx]);if(schrijfGebruikers($usersBestand,$gebruikers)){schrijfLog($logBestand,$huidigeGebruiker,$nieuwActief?'gebruiker_geactiveerd':'gebruiker_geblokkeerd',$naam.' · bestaande sessies ingetrokken');guFlash('Account “'.$naam.'” is '.($nieuwActief?'geactiveerd.':'geblokkeerd. Bestaande sessies zijn ingetrokken.'));}else guFlash('Accountstatus kon niet worden opgeslagen.','fout');}
        }elseif($actie==='sessies_intrekken'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$idx=guVindIndex($gebruikers,$naam);
            if($idx===null)guFlash('Gebruiker niet gevonden.','fout');else{guTrekSessiesIn($gebruikers[$idx]);if(schrijfGebruikers($usersBestand,$gebruikers)){schrijfLog($logBestand,$huidigeGebruiker,'sessies_ingetrokken',$naam);guFlash('Alle bestaande sessies van “'.$naam.'” zijn ingetrokken.');}else guFlash('Sessies konden niet worden ingetrokken.','fout');}
        }elseif($actie==='login_vrijgeven'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$idx=guVindIndex($gebruikers,$naam);if($idx===null)guFlash('Gebruiker niet gevonden.','fout');elseif(loginPogingenWissen($loginPogingenBestand,'user:'.strtolower($naam))){schrijfLog($logBestand,$huidigeGebruiker,'login_lockout_vrijgegeven',$naam);guFlash('Loginpogingen van “'.$naam.'” zijn gewist.');}else guFlash('Loginpogingen konden niet worden gewist.','fout');
        }elseif($actie==='verwijderen'){
            $naam=trim((string)($_POST['gebruikersnaam']??''));$bevestiging=trim((string)($_POST['bevestiging']??''));$idx=guVindIndex($gebruikers,$naam);
            if($idx===null)guFlash('Gebruiker niet gevonden.','fout');elseif(strcasecmp($naam,$huidigeGebruiker)===0&&!$isMaster)guFlash('Je kunt het account waarmee je bent ingelogd niet verwijderen.','fout');elseif($bevestiging!==$naam)guFlash('Verwijderen geweigerd: typ de gebruikersnaam exact over ter bevestiging.','fout');else{array_splice($gebruikers,$idx,1);if(schrijfGebruikers($usersBestand,$gebruikers)){loginPogingenWissen($loginPogingenBestand,'user:'.strtolower($naam));schrijfLog($logBestand,$huidigeGebruiker,'gebruiker_verwijderd',$naam);guFlash('Account “'.$naam.'” is verwijderd.');}else guFlash('Account kon niet worden verwijderd.','fout');}
        }else guFlash('Onbekende gebruikersactie.','fout');
    }finally{dataSlotDicht($slot);}guRedirect();
}

$gebruikers=laadGebruikers($usersBestand);usort($gebruikers,static fn($a,$b)=>strcasecmp((string)($a['gebruikersnaam']??''),(string)($b['gebruikersnaam']??'')));
$logOverzicht=guLeesLogOverzicht($logBestand);$alleLoginPogingen=laadLoginPogingen($loginPogingenBestand);$aantalMetGebruikersrecht=0;$aantalLegacy=0;$aantalGeblokkeerd=0;
foreach($gebruikers as $g){$tabs=$g['tabs']??null;if(!is_array($tabs))$aantalLegacy++;if(is_array($tabs)&&in_array('gebruikers',$tabs,true))$aantalMetGebruikersrecht++;if(($g['actief']??true)===false)$aantalGeblokkeerd++;}
