(--ok)}.pwcheck.warn{color:var(--warn)}.pwcheck.fout{color:var(--danger)}.pwrow{display:flex;gap:7px}.preset{margin-bottom:10px}.preset button{font-size:12px;padding:6px 9px}@media(max-width:850px){.stats{grid-template-columns:1fr 1fr}.grid2,.rights{grid-template-columns:1fr}.account-head{align-items:flex-start;flex-direction:column}.badges{justify-content:flex-start}}@media(max-width:520px){.wrap{padding-left:12px;padding-right:12px}.stats{grid-template-columns:1fr}.pwrow,.securitybox,.pwtools{flex-direction:column;align-items:stretch}}
