c($groep)?></h4><?php foreach($items as $key=>$label):?><label class="check"><input type="checkbox" name="tabs[]" value="<?=guEsc($key)?>"><span><?=guEsc($label)?><?php if(in_array($key,$gevoeligeRechten,true)):?> <small>gevoelig</small><?php endif;?></span></label><?php endforeach;?></div><?php endforeach;?></div></div><div><button class="btn primary">Account aanmaken</button></div></form></section>
