<article class="account <?=$actief?'':'inactive'?>" data-user="<?=guEsc($k)?>"><div class="account-head"><div class="ident"><div class="avatar"><?=guEsc(strtoupper(substr($naam,0,1)))?></div><div><div class="naam"><?=guEsc($naam)?></div><div class="meta">Aangemaakt: <?=guEsc(guAangemaakt($g))?> · Laatste login: <?=guEsc(guDatum($logOverzicht['login'][$k]??null))?><br>Laatste beheeractie: <?=guEsc(guDatum($logOverzicht['actie'][$k]??null))?> · Wachtwoord gewijzigd: <?=guEsc(guWachtwoordDatum($g))?></div></div></div><div class="badges"><span class="badge"><?=count($effectief)?> recht(en)</span><?php if(!$actief):?><span class="badge off">geblokkeerd</span><?php endif;?><?php if($sens):?><span class="badge sens">hoog vertrouwen</span><?php endif;?><?php if($legacy):?><span class="badge legacy">legacy brede toegang</span><?php endif;?><?php if($loginStatus['geblokkeerd']):?><span class="badge locked">login tijdelijk geblokkeerd</span><?php elseif($loginStatus['aantal']):?><span class="badge attempt"><?=$loginStatus['aantal']?> mislukte poging(en)</span><?php endif;?></div></div>
<details><summary>Rechten beheren</summary><div class="detailbody"><?php if($legacy):?><div class="waarschuwing"><strong>Legacy-account:</strong> sla een expliciete selectie op om de toegang voorspelbaar te maken.</div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=guEsc($csrfToken)?>"><input type="hidden" name="actie" value="rechten"><input type="hidden" name="gebruikersnaam" value="<?=guEsc($naam)?>"><div class="preset"><button class="btn secondary preset" type="button" data-preset="content">Contentbeheer</button><button class="btn secondary preset" type="button" data-preset="communicatie">Communicatie</button><button class="btn secondary preset" type="button" data-preset="penningmeester">Penningmeester</button><button class="btn secondary preset" type="button" data-preset="alles">Volledig beheer</button><button class="btn secondary preset" type="button" data-preset="geen">Alles wissen</button></div><div class="rights"><?php foreach($rechtGroepen as $groep=>$items):?><div class="rechtgroep"><h4><?=guEsc($groep)?></h4><?php foreach($items as $key=>$label):?><label class="check"><input type="checkbox" name="tabs[]" value="<?=guEsc($key)?>" <?=in_array($key,$effectief,true)?'checked':''?>><span><?=guEsc($label)?><?php if(in_array($key,$gevoeligeRechten,true)):?> <small>gevoelig</small><?php endif;?></span></label><?php endforeach;?></div><?php endforeach;?></div><div class="actierij"><button class="btn primary">Rechten opslaan</button></div></form></div></details>
<details><summary>Wachtwoord wijzigen</summary><div class="detailbody"><form method="post" class="velden wachtwoord-form"><input type="hidden" name="csrf" value="<?=guEsc($csrfToken)?>"><input type="hidden" name="actie" value="wachtwoord"><input type="hidden" name="gebruikersnaam" value="<?=guEsc($naam)?>"><div class="pwfields"><div class="veld"><label>Nieuw wachtwoord</label><div class="pwfield"><input class="pw1 wachtwoord-input" type="password" name="wachtwoord" minlength="10" required><button class="eye showpw" type="button">◉</button></div></div><div class="veld"><label>Herhaal nieuw wachtwoord</label><div class="pwfield"><input class="pw2 wachtwoord-input" type="password" name="wachtwoord_herhaald" minlength="10" required><button class="eye showpw" type="button">◉</button></div></div><div class="pwcheck"></div></div><div class="pwtools"><span class="hint">Minimaal 10 tekens.</span><button class="btn secondary genpw" type="button">Genereer sterk wachtwoord</button></div><button class="btn primary">Wachtwoord wijzigen</button></form></div></details>
<details><summary>Beveiliging</summary><div class="detailbody"><div class="securitybox"><div><strong>Accountstatus</strong><div class="hint"><?=$actief?'Account is actief en kan inloggen.':'Account is geblokkeerd; toegang en bestaande sessies zijn uitgeschakeld.'?></div></div><form method="post"><input type="hidden" name="csrf" value="<?=guEsc($csrfToken)?>"><input type="hidden" name="actie" value="status"><input type="hidden" name="gebruikersnaam" value="<?=guEsc($naam)?>"><input type="hidden" name="actief" value="<?=$actief?'0':'1'?>"><button class="btn <?=$actief?'danger':'primary'?>" type="submit"><?=$actief?'Account blokkeren':'Account activeren'?></button></form></div><div class="securitybox"><div><strong>Sessies</strong><div class="hint">Laat dit account op alle apparaten opnieuw inloggen.</div></div><form method="post"><input type="hidden" name="csrf" value="<?=guEsc($csrfToken)?>"><input type="hidden" name="actie" value="sessies_intrekken"><input type="hidden" name="gebruikersnaam" value="<?=guEsc($naam)?>"><button class="btn secondary">Alle sessies uitloggen</button></form></div><div class="securitybox"><div><strong>Loginbeveiliging</strong><div class="hint"><?php if($loginStatus['geblokkeerd']):?><?=$loginStatus['aantal']?> recente mislukte pogingen; nog ongeveer <?=$loginStatus['minuten']?> minuut/minuten geblokkeerd.<?php elseif($loginStatus['aantal']):?><?=$loginStatus['aantal']?> van maximaal <?=$loginLockoutDrempel?> mislukte pogingen in de laatste 15 minuten.<?php else:?>Geen recente mislukte inlogpogingen.<?php endif;?></div></div><?php if($loginStatus['aantal']):?><form method="post"><input type="hidden" name="csrf" value="<?=guEsc($csrfToken)?>"><input type="hidden" name="actie" value="login_vrijgeven"><input type="hidden" name="gebruikersnaam" value="<?=guEsc($naam)?>"><button class="btn secondary">Loginpogingen wissen</button></form><?php endif;?></div><p class="hint">De aparte IP-beveiliging tegen brute-force blijft altijd actief.</p></div></details>
<details><summary style="color:var(--danger)">Account verwijderen</summary><div class="detailbody"><div class="dangerzone"><strong>Permanent verwijderen</strong><p class="hint">Voor tijdelijk geen toegang: gebruik liever <strong>Account blokkeren</strong>. Typ <strong><?=guEsc($naam)?></strong> om permanent te verwijderen.</p><form method="post"><input type="hidden" name="csrf" value="<?=guEsc($csrfToken)?>"><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="gebruikersnaam" value="<?=guEsc($naam)?>"><div class="pwrow"><input name="bevestiging" required placeholder="<?=guEsc($naam)?>"><button class="btn danger">Account verwijderen</button></div></form></div></div></details></article><?php endforeach;?><?php if(!$gebruikers):?><div class="card">Er zijn nog geen gewone beheeraccounts.</div><?php endif;?></div></main>
<script>
const presets={content:['homepage','ontstaan','baanreglement','aanmelden','bedankt','mededeling','nieuws','agenda','contact','sponsors','faq','media','fotoboek'],communicatie:['mededeling','nieuws','agenda','contact','sponsors','faq','media','fotoboek','changelog'],penningmeester:['rekentabel','backups','log'],alles:<?=json_encode(array_keys($alleRechten))?>,geen:[]};
function sterkWachtwoord(){const c='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%+-_';const a=new Uint32Array(20);crypto.getRandomValues(a);return Array.from(a,n=>c[n%c.length]).join('');}
function feedback(f){const a=f.querySelector('.pw1'),b=f.querySelector('.pw2'),o=f.querySelector('.pwcheck');if(!a||!b||!o)return;if(!a.value&&!b.value){o.textContent='';o.className='pwcheck';return}if(a.value.length<10){o.textContent='Nog '+(10-a.value.length)+' teken(s) nodig.';o.className='pwcheck warn';return}if(!b.value){o.textContent='Lengte is goed. Herhaal het wachtwoord.';o.className='pwcheck warn';return}if(a.value!==b.value){o.textContent='De wachtwoorden zijn niet gelijk.';o.className='pwcheck fout';return}o.textContent='✓ Wachtwoorden zijn gelijk en lang genoeg.';o.className='pwcheck ok'}
document.querySelectorAll('.wachtwoord-input').forEach(i=>{i.addEventListener('invalid',()=>{if(i.validity.valueMissing)i.setCustomValidity('Vul een wachtwoord in.');else if(i.validity.tooShort)i.setCustomValidity('Gebruik minimaal 10 tekens.')});i.addEventListener('input',()=>{i.setCustomValidity('');feedback(i.closest('.wachtwoord-form'))})});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('genpw')){const f=b.closest('form'),p=sterkWachtwoord();f.querySelector('.pw1').value=p;f.querySelector('.pw2').value=p;feedback(f)}if(b.classList.contains('showpw')){const i=b.closest('.pwfield').querySelector('input');i.type=i.type==='password'?'text':'password';b.textContent=i.type==='text'?'⊘':'◉';b.title=i.type==='text'?'Wachtwoord verbergen':'Wachtwoord tonen';b.setAttribute('aria-label',b.title)}if(b.dataset.preset){const f=b.closest('form'),set=new Set(presets[b.dataset.preset]||[]);f.querySelectorAll('input[name="tabs[]"]').forEach(c=>c.checked=set.has(c.value))}});
const z=document.getElementById('account-search');if(z)z.addEventListener('input',()=>{const q=z.value.trim().toLowerCase();document.querySelectorAll('.account').forEach(a=>a.hidden=q&&!a.dataset.user.includes(q))});
</script></body></html>